window.initializeAlgerianLocationSelects = function (wilayaSelect, municipalitySelect) {
  const wilayas = new Map();
  window.ALGERIA_LOCATIONS.forEach(({ wilaya_code, wilaya_name_ar }) => wilayas.set(wilaya_code, wilaya_name_ar));
  wilayaSelect.replaceChildren(new Option('اختر الولاية', ''));
  [...wilayas].sort((first, second) => Number(first[0]) - Number(second[0]))
    .forEach(([code, name]) => wilayaSelect.add(new Option(name, code)));
  municipalitySelect.replaceChildren(new Option('اختر البلدية', ''));
  municipalitySelect.disabled = true;
  wilayaSelect.addEventListener('change', () => {
    municipalitySelect.replaceChildren(new Option('اختر البلدية', ''));
    const municipalities = window.ALGERIA_LOCATIONS
      .filter(location => location.wilaya_code === wilayaSelect.value)
      .sort((first, second) => first.commune_name_ar.localeCompare(second.commune_name_ar, 'ar'));
    municipalities.forEach(location => municipalitySelect.add(new Option(location.commune_name_ar, location.commune_name_ar)));
    municipalitySelect.disabled = municipalities.length === 0;
  });
};